 z-index: 100;\n47: \theight: var(--header-h);\n48: \tbackground: var(--bg-secondary);\n49: \tborder-bottom: 1px solid var(--border);\n50: \tdisplay: flex; align-items: center; padding: 0 24px;\n51: }\n52: .header-logo {\n53: \tfont-size: 1.25rem; font-weight: 700; color: var(--text);\n54: \tdisplay: flex; align-items: center; gap: 10px;\n55: }\n56: .header-links { margin-left: auto; display: flex; gap: 20px; align-items: center; }\n57: .header-links a { color: var(--text-secondary); font-size: .875rem; font-weight: 500; }\n58: .header-links a:hover { color: var(--text); text-decoration: none; }\n59: \n60: /* ── Sidebar ────────────────────────────────────────────────────────── */\n61: .sidebar {\n62: \tposition: fixed; top: var(--header-h); left: 0; bottom: 0;\n63: \twidth: var(--sidebar-w); background: var(--bg-secondary);\n64: \tborder-right: 1px solid var(--border);\n65: \toverflow-y: auto; padding: 16px 0;\n66: }\n67: .sidebar-section { padding: 0 12px; margin-bottom: 8px; }\n68: .sidebar-section-title {\n69: \tfont-size: .75rem; font-weight: 600; text-transform: uppercase;\n70: \tletter-spacing: .05em; color: var(--text-muted);\n71: \tpadding: 8px 12px 4px;\n72: }\n73: .sidebar a {\n74: \tdisplay: block; padding: 6px 12px; border-radius: 6px;\n75: \tfont-size: .875rem; color: var(--text-secondary); line-height: 1.4;\n76: }\n77: .sidebar a:hover { background: var(--bg-tertiary); color: var(--text); text-decoration: none; }\n78: .sidebar a.active {\n79: \tbackground: var(--accent-subtle); color: var(--accent); font-weight: 500;\n80: }\n81: \n82: /* ── Mobile menu ────────────────────────────────────────────────────── */\n83: .menu-toggle {\n84: \tdisplay: none; background: none; border: none; color: var(--text);\n85: \tfont-size: 1.5rem; cursor: pointer; padding: 4px 8px;\n86: }\n87: @media (max-width: 768px) {\n88: \t.sidebar {\n89: \t\ttransform: translateX(-100%); transition: transform .2s ease;\n90: \t\tz-index: 99; width: 280px;\n91: \t}\n92: \t.sidebar.open { transform: translateX(0); }\n93: \t.sidebar-backdrop {\n94: \t\tposition: fixed; inset: 0; z-index: 98;\n95: \t\tbackground: rgba(0,0,0,.5); backdrop-filter: blur(2px);\n96: \t\tdisplay: none;\n97: \t}\n98: \t.sidebar-backdrop.visible { display: block; }\n99: \t.menu-toggle { display: block; margin-right: 8px; }\n100: \t.main { margin-left: 0 !important; padding: 20px 16px 60px !important; }\n101: \t.header { padding: 0 12px; }\n102: \t.header-links { gap: 14px; }\n103: \n104: \t/* Hero */\n105: \t.hero { padding: 56px 16px 40px; }\n106: \t.hero h1 { font-size: 2rem; }\n107: \t.hero p { font-size: 1rem; margin-bottom: 24px; }\n108: \t.hero-buttons a { padding: 10px 22px; font-size: .9rem; }\n109: \t.install-block { margin-top: 24px; padding: 12px 14px; }\n110: \t.install-block code { font-size: .75rem; word-break: break-all; }\n111: \n112: \t/* Features */\n113: \t.features { grid-template-columns: 1fr; padding: 24px 16px 40px; gap: 12px; }\n114: \t.feature { padding: 16px; }\n115: \n116: \t/* Providers */\n117: \t.providers { padding: 24px 16px; }\n118: \t.providers h2 { font-size: 1.25rem; }\n119: \n120: \t/* Docs grid */\n121: \t.landing-docs { padding: 24px 16px 60px; }\n122: \t.landing-docs h2 { font-size: 1.25rem; }\n123: \t.docs-grid { grid-template-columns: 1fr; }\n124: \n125: \t/* Content */\n126: \t.content h1 { font-size: 1.5rem; }\n127: \t.content h2 { font-size: 1.25rem; margin: 28px 0 10px; }\n128: \t.content h3 { font-size: 1.1rem; }\n129: \t.content table { font-size: .8rem; }\n130: \t.content th, .content td { padding: 6px 8px; }\n131: \t.content pre:not(.mermaid-code) { padding: 12px; font-size: .8rem; }\n132: \n133: \t/* Mermaid */\n134: \t.mermaid-diagram { padding: 12px; max-height: 45vh; }\n135: \t.mermaid-code { max-height: 45vh; }\n136: \t.mermaid-toolbar { padding: 6px 8px; }\n137: \t.mermaid-toolbar button { padding: 3px 8px; font-size: .75rem; }\n138: }\n139: \n140: /* ── Main content ───────────────────────────────────────────────────── */\n141: .main {\n142: \tmargin-left: var(--sidebar-w);\n143: \tmargin-top: var(--header-h);\n144: \tpadding: 32px 48px 80px;\n145: \tmax-width: 900px;\n146: }\n147: .main-landing {\n148: \tmargin-left: 0; max-width: none; padding: 0;\n149: }\n150: \n151: /* ── Typography ─────────────────────────────────────────────────────── */\n152: .content h1 { font-size: 2rem; font-weight: 700; margin: 0 0 16px; line-height: 1.3; }\n153: .content h2 {\n154: \tfont-size: 1.5rem; font-weight: 600; margin: 40px 0 12px;\n155: \tpadding-bottom: 8px; border-bottom: 1px solid var(--border);\n156: }\n157: .content h3 { font-size: 1.2rem; font-weight: 600; margin: 28px 0 8px; }\n158: .content h4 { font-size: 1rem; font-weight: 600; margin: 20px 0 6px; }\n159: .content p { margin: 0 0 16px; }\n160: .content ul, .content ol { margin: 0 0 16px; padding-left: 24px; }\n161: .content li { margin: 4px 0; }\n162: .content strong { font-weight: 600; }\n163: .content hr { border: none; border-top: 1px solid var(--border); margin: 32px 0; }\n164: .content blockquote {\n165: \tborder-left: 3px solid var(--accent); padding: 8px 16px;\n166: \tmargin: 0 0 16px; background: var(--accent-subtle); border-radius: 0 6px 6px 0;\n167: }\n168: .content blockquote p:last-child { margin-bottom: 0; }\n169: \n170: /* ── Code ───────────────────────────────────────────────────────────── */\n171: .content code {\n172: \tfont-family: var(--font-mono); font-size: .875em;\n173: \tbackground: var(--code-bg); padding: 2px 6px; border-radius: 4px;\n174: \tborder: 1px solid var(--border);\n175: }\n176: .content pre:not(.mermaid-code) {\n177: \tbackground: var(--code-bg); border: 1px solid var(--border);\n178: \tborder-radius: 8px; padding: 16px; margin: 0 0 16px;\n179: \toverflow-x: auto; line-height: 1.5;\n180: }\n181: .content pre:not(.mermaid-code) code {\n182: \tbackground: none; border: none; padding: 0; font-size: .875rem;\n183: }\n184: \n185: /* ── Mermaid ────────────────────────────────────────────────────────── */\n186: .mermaid-viewer {\n187: \tbackground: var(--code-bg); border: 1px solid var(--border);\n188: \tborder-radius: 8px; margin: 0 0 16px; overflow: hidden;\n189: }\n190: .mermaid-toolbar {\n191: \tdisplay: flex; align-items: center; gap: 6px;\n192: \tpadding: 8px 12px; border-bottom: 1px solid var(--border);\n193: \tbackground: var(--bg-tertiary);\n194: }\n195: .mermaid-toolbar button {\n196: \tbackground: var(--bg-secondary); border: 1px solid var(--border);\n197: \tcolor: var(--text-secondary); border-radius: 4px;\n198: \tpadding: 4px 10px; font-size: .8rem; cursor: pointer;\n199: \tfont-family: var(--font); line-height: 1;\n200: }\n201: .mermaid-toolbar button:hover { color: var(--text); border-color: var(--accent); }\n202: .mermaid-toolbar button.active { color: var(--accent); border-color: var(--accent); }\n203: .mermaid-toolbar .zoom-label {\n204: \tfont-size: .75rem; color: var(--text-muted); margin-left: auto;\n205: }\n206: .mermaid-diagram {\n207: \tpadding: 24px; overflow: hidden; max-height: 60vh;\n208: \tposition: relative; cursor: grab; user-select: none;\n209: \ttouch-action: none; -webkit-user-select: none;\n210: }\n211: .mermaid-diagram.dragging { cursor: grabbing; }\n212: .mermaid-diagram svg { transition: none; transform-origin: 0 0; }\n213: .mermaid-code {\n214: \tdisplay: none; padding: 16px; margin: 0;\n215: \tbackground: none; border: none;\n216: \tfont-family: var(--font-mono); font-size: .8rem;\n217: \tcolor: var(--text-secondary); line-height: 1.5;\n218: \toverflow-x: auto; max-height: 60vh;\n219: }\n220: .mermaid-code.visible { display: block; }\n221: \n222: /* ── Tables ─────────────────────────────────────────────────────────── */\n223: .table-wrap { overflow-x: auto; margin: 0 0 16px; border: 1px solid var(--border); border-radius: 8px; }\n224: .content table {\n225: \twidth: 100%; border-collapse: collapse; margin: 0;\n226: \tfont-size: .875rem;\n227: }\n228: .content th, .content td {\n229: \tpadding: 8px 12px; border: 1px soli