// Password policy for the signup flow:
//   - at least 8 characters (Unicode code points, not UTF-16 code units)
//   - at least one digit
//   - at least one uppercase letter
//   - at least one special character (punctuation/symbol; whitespace and
//     control characters do not count)
function validatePassword(password) {
  if (typeof password !== 'string') {
    return false;
  }
  // Array.from counts code points, so an emoji counts as one character
  // instead of the two UTF-16 code units String#length would report.
  if (Array.from(password).length < 8) {
    return false;
  }
  if (!/\p{Nd}/u.test(password)) {
    return false;
  }
  if (!/\p{Lu}/u.test(password)) {
    return false;
  }
  // \p{P} covers punctuation, \p{S} covers symbols like !?@#$%^&*+<=>|~.
  // Excluding \p{C} (control/format chars) and \p{Z} (separators) keeps a
  // trailing space or a NUL from satisfying the "special character" rule.
  if (!/[\p{P}\p{S}]/u.test(password)) {
    return false;
  }
  return true;
}

