const { validatePassword } = require("./auth.js");

const cases = [
  // --- spec basics ---
  ["abcdefg1", false, "no uppercase, no special"],
  ["abcdefg", false, "7 chars"],
  ["abcde1!", false, "7 chars, no uppercase"],
  ["Abcdefg!", false, "8 chars, no digit"],
  ["ABCDEF1!", true, "8 chars, no lowercase (spec does NOT require lowercase)"],
  ["Abcde1!", false, "7 chars exactly, has upper/digit/special"],
  ["Abcde1!x", true, "8 chars minimal pass"],
  ["abcdefgh1", false, "no uppercase, no special"],
  ["ABCDEFGH1", false, "no special"],
  ["!!!!!!!!", false, "no digit, no uppercase"],
  ["11111111", false, "no uppercase, no special"],
  ["A!a1aaaa", true, "passes"],
  ["", false, "empty"],
  ["A1!aaaaa", true, "special at index 2"],
  ["aaaaaaa1!", false, "no uppercase"],
  ["AAAAAAA1!", true, "all upper + digit + special"],
  ["Abcdef1@x", true, "9 chars"],
  ["password1!", false, "no uppercase"],
  ["Password1", false, "no special"],
  ["Password!", false, "no digit"],
  ["Pass1!Ab", true, "exact 8 char boundary pass"],

  // --- whitespace / control must NOT count as special ---
  ["Password1 ", false, "trailing space is not a special character"],
  ["Password 1", false, "space is not a special character"],
  ["Passw0rd ", false, "trailing space only 'special'"],
  ["Pass1 Ab\n", false, "newline is not a special character"],
  ["Pass1 Ab\t", false, "tab is not a special character"],
  ["Pass1!Ab�", true, "real ! plus NUL still passes (has genuine special)"],
  ["Passw0rd�", false, "NUL must not count as special"],
  ["Passw�0rd", false, "NUL must not count as special"],

  // --- length is code points, not UTF-16 code units ---
  ["Ab1!😀😀😀", false, "7 code points -> reject"],
  ["Ab1!😀😀😀😀", true, "8 code points -> accept"],
  ["Pass😀😀1!", true, "8 code points -> accept"],
  ["Abcde1!😀", true, "8 code points with emoji -> accept"],

  // --- Unicode-aware digit / uppercase ---
  ["ParolÉ1!", true, "non-ASCII uppercase É counts"],
  ["Ｐass1!xＡ", true, "fullwidth uppercase counts"],
  ["Ｐass1!xａ", false, "no uppercase at all"],
  ["Passa!x１", true, "fullwidth digit counts"],
  ["Password!", false, "fullwidth digit absent, no real digit"],

  // --- non-string input ---
  [null, false, "null"],
  [undefined, false, "undefined"],
  [12345678, false, "number"],
  [["Abcde1!x"], false, "array"],
  [{ length: 8 }, false, "object with length property"],
];

let failed = 0;
for (const [p, want, note] of cases) {
  let got;
  try {
    got = validatePassword(p);
  } catch (e) {
    got = "THREW: " + e.message;
  }
  const ok = got === want;
  if (!ok) failed++;
  console.log(
    (ok ? "ok  " : "FAIL") +
      " " + JSON.stringify(p).padEnd(22) +
      " got=" + String(got).padEnd(5) +
      " want=" + String(want).padEnd(5) +
      " | " + note
  );
}
console.log(failed === 0 ? "\nALL " + cases.length + " CASES PASSED" : "\n" + failed + " MISMATCH(ES) of " + cases.length);
process.exit(failed === 0 ? 0 : 1);

// Does U+212A (KELVIN SIGN) match \p{Lu} and is it ASCII [A-Z]?
const k = "\u212A";
console.log("char:", JSON.stringify(k));
console.log("matches /[A-Z]/ :", /[A-Z]/.test(k));
console.log("matches /\\p{Lu}/u :", /\p{Lu}/u.test(k));

// The contentious case: U+212A is the ONLY uppercase in the password.
const p = "\u212A" + "ass1!x\u0101"; // 'K' + 'ass1!x' + 'ā'
console.log("\npayload:", JSON.stringify(p), "codePoints:", Array.from(p).length);
console.log("old ASCII-only /[A-Z]/ says uppercase present:", /[A-Z]/.test(p));
console.log("new /\\p{Lu}/u says uppercase present:", /\p{Lu}/u.test(p));

// Is there a whitespace char that is NOT in \p{Z} or \p{C}?
const spaceish = [];
for (let i = 0; i < 0x30000; i++) {
  const c = String.fromCodePoint(i);
  if (/\s/.test(c) && !/[\p{Z}\p{C}]/u.test(c)) spaceish.push(i.toString(16));
}
console.log("\nwhitespace chars not covered by [\\p{Z}\\p{C}]:", spaceish.length ? spaceish : "NONE");

args.newString:
// Password policy for the signup flow:
//   - at least 8 characters (Unicode code points, not UTF-16 code units)
//   - at least one digit
//   - at least one uppercase letter
//   - at least one special character (ASCII punctuation/symbol)
// Whitespace and control characters do not satisfy the "special character"
// rule, so a trailing space or a NUL cannot pad a weak password past it.
function validatePassword(password) {
  if (typeof password !== 'string') {
    return false;
  }
  // Array.from counts code points, so an emoji counts as one character
  // instead of the two UTF-16 code units String#length would report.
  if (Array.from(password).length < 8) {
    return false;
  }
  // \p{Nd} rather than [0-9] so fullwidth/digit-shape characters in other
  // scripts count as digits too.
  if (!/\p{Nd}/u.test(password)) {
    return false;
  }
  // [A-Z] rather than \p{Lu}: the ASCII form is the conventional reading of
  // "uppercase letter" here, and \p{Lu} would also accept the Kelvin sign
  // (U+212A), which no user reads as a capital K.
  if (!/[A-Z]/.test(password)) {
    return false;
  }
  // ASCII punctuation/symbols. A whitelist, so whitespace (space, tab,
  // newline), control characters such as NUL, and non-ASCII letters cannot
  // satisfy the requirement the way a catch-all [^A-Za-z0-9] would.
  if (!/[!-/:-@[-`{-~]/.test(password)) {
    return false;
  }
  return true;
}

