// Password policy: at least 8 characters, and must contain at least one digit,
// one uppercase letter, and one special character.
const MIN_LENGTH = 8;
const HAS_DIGIT = /[0-9]/;
const HAS_UPPERCASE = /[A-Z]/;
// "Special" means any non-alphanumeric character other than whitespace: whitespace
// is a poor choice for a character class the user is meant to type deliberately.
const HAS_SPECIAL = /[^A-Za-z0-9\s]/;

function validatePassword(password) {
  if (typeof password !== "string") {
    return false;
  }
  if (password.length < MIN_LENGTH) {
    return false;
  }
  if (!HAS_DIGIT.test(password)) {
    return false;
  }
  if (!HAS_UPPERCASE.test(password)) {
    return false;
  }
  if (!HAS_SPECIAL.test(password)) {
    return false;
  }
  return true;
}

